 out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated/primaryP1_enriched_finite_domain1/summary.json';s=json.loads(src.read_text());trial=json.loads((REPO/s['source']['path']).read_text());e=np.load(REPO/trial['output']['path']);field=np.load(REPO/s['source_field']['path']);old=json.loads((ROOT/'validation/integrated/primaryP1_ritz_primaldual1/summary.json').read_text());r=load_ritz(json.loads((REPO/old['source']['path']).read_text()));dx=e['proposed_x']-r['before_x'];X=field['F0_ROOT_BACK_points_mm'];Y=field['OPEN_FRAME_points_mm'];ro=int(field['F0_ROOT_BACK_offset']);fo=int(field['OPEN_FRAME_offset']);dr=np.asarray(dx[ro:ro+3*len(X)].reshape(-1,3),dtype=float);df=np.asarray(dx[fo:fo+3*len(Y)].reshape(-1,3),dtype=float);xr=X+field['u_mm'][ro:ro+3*len(X)].reshape(-1,3)+dr;yf=Y+field['u_mm'][fo:fo+3*len(Y)].reshape(-1,3)+df;lookup={tuple(np.round(p,7)):i for i,p in enumerate(X)};rows=[];checks={}
